// provider-ppq-panels.js - PPQ account, balance, and top-up panel behavior.
import { getErrorMessage } from './caught-error.js';
import { escapeHTML, escapeAttr, showNotification, showConfirmDialog } from './utils.js';
import { getPpqKey, savePpqKey, fetchPpqModels, validatePpqKey, createPpqAccount, getPpqBalance, savePpqCreditId, createPpqTopup, checkPpqTopupStatus, } from './api.js';
import { updateKeyCache } from './crypto.js';
import { ensureQRCode } from './provider-qr.js';
import { renderAIProviderPanel } from './provider-panel-renderers.js';
import { renderPpqModelDropdown } from './provider-model-controls.js';
import { getSettingsModuleFunction } from './settings-runtime-bridge.js';
let returnToChatIfOnboarding = function () { };
let requestProviderActivation = async function () { return true; };
let _ppqCreating = false;
let _ppqTopupPollTimer = null;
let _ppqCountdownTimer = null;
export function configurePpqPanels(options = {}) {
  if (typeof options.returnToChatIfOnboarding === 'function') {
    returnToChatIfOnboarding = options.returnToChatIfOnboarding;
  }
  if (typeof options.requestProviderActivation === 'function') {
    requestProviderActivation = options.requestProviderActivation;
  }
}
export function clearPpqTopupTimers() {
  if (_ppqTopupPollTimer) {
    clearInterval(_ppqTopupPollTimer);
    _ppqTopupPollTimer = null;
  }
  if (_ppqCountdownTimer) {
    clearInterval(_ppqCountdownTimer);
    _ppqCountdownTimer = null;
  }
}
function _setCopiedText(actionEl, fallback = '✓ Copied') {
  if (actionEl instanceof HTMLElement) {
    actionEl.textContent = actionEl.dataset.copiedText || fallback;
  }
}
async function _copyPanelText(text, actionEl) {
  if (!text)
    return false;
  try {
    await navigator.clipboard.writeText(text);
    _setCopiedText(actionEl);
    return true;
  }
  catch (e) {
    showNotification(`Copy failed: ${getErrorMessage(e, e)}`, 'error');
    return false;
  }
}
export function copyPpqKeyReveal(actionEl) {
  const text = actionEl?.dataset?.clipboardText || '';
  const appWindow = window;
  void _copyPanelText(text, actionEl).then((copied) => {
    if (!copied)
      return;
    clearTimeout(appWindow._ppqClipTimer);
    appWindow._ppqClipTimer = setTimeout(() => navigator.clipboard?.writeText?.(''), 60000);
  });
}
export function handleSelectPpqMethod(actionEl) {
  const methodId = actionEl?.dataset?.ppqMethod || '';
  if (methodId)
    selectPpqMethod(methodId);
}
export function handlePpqTopupPreset(actionEl) {
  const amount = Number(actionEl?.dataset?.amount);
  if (Number.isFinite(amount))
    void doPpqTopup(amount);
}
export function copyPpqPayment(actionEl) {
  void _copyPanelText(actionEl?.dataset?.clipboardText || '', actionEl);
}
function _ppqBalanceHtml(balance) {
  const v = parseFloat(balance);
  const color = v < 0.10 ? 'var(--red)' : v < 0.50 ? 'var(--yellow, #f0a800)' : 'var(--green)';
  return 'Balance: <span style="color:' + color + '">$' + v.toFixed(2) + '</span>';
}
function _hasCachedPpqPrivateModels() {
  try {
    return JSON.parse(localStorage.getItem('labcharts-ppq-private-models') || '[]').length > 0;
  }
  catch {
    return false;
  }
}
function _rerenderPpqPanelIfPrivateControlsAppeared() {
  if (document.getElementById('ppq-private-toggle') || !_hasCachedPpqPrivateModels())
    return false;
  const panel = document.getElementById('ai-provider-panel');
  if (!panel || !panel.querySelector('#ppq-model-area'))
    return false;
  panel.innerHTML = renderAIProviderPanel('ppq');
  return true;
}
function _renderPpqBalanceValue(balance) {
  const el = document.getElementById('ppq-balance');
  if (el && balance != null) {
    el.innerHTML = _ppqBalanceHtml(balance);
    if (parseFloat(balance) === 0 && document.getElementById('ppq-topup-area'))
      showPpqTopup();
  }
  else if (el)
    el.textContent = 'Balance: unavailable';
}
function _refreshPpqBalanceDisplay() {
  return getPpqBalance().then(_renderPpqBalanceValue);
}
function _renderPpqModelsAfterFetch(models) {
  const rerendered = _rerenderPpqPanelIfPrivateControlsAppeared();
  if (models.length)
    renderPpqModelDropdown(models);
  if (rerendered)
    _refreshPpqBalanceDisplay();
}
export function initSettingsPpqPanel() {
  const ppqKey = getPpqKey();
  if (ppqKey && document.getElementById('ppq-model-area')) {
    fetchPpqModels(ppqKey).then(_renderPpqModelsAfterFetch);
    _refreshPpqBalanceDisplay();
  }
}
export async function handleCreatePpqAccount() {
  if (_ppqCreating)
    return;
  _ppqCreating = true;
  const createBtn = document.querySelector('[data-provider-panel-action="create-ppq-account"]');
  if (createBtn) {
    createBtn.disabled = true;
    createBtn.textContent = 'Creating\u2026';
  }
  const status = document.getElementById('ppq-key-status');
  if (status)
    status.innerHTML = '<span style="color:var(--text-muted)">Creating account\u2026</span>';
  try {
    const result = await createPpqAccount();
    if (!result.success && !result.api_key)
      throw new Error('Account creation failed');
    await savePpqKey(result.api_key);
    savePpqCreditId(result.credit_id);
    await fetchPpqModels(result.api_key);
    const activated = await requestProviderActivation('ppq');
    const panel = document.getElementById('ai-provider-panel');
    if (panel) {
      panel.innerHTML = `<div class="ai-provider-panel">
        <div style="padding:12px;background:var(--bg-secondary);border-radius:8px;border:1px solid var(--accent)">
          <div style="font-size:13px;font-weight:600;color:var(--accent);margin-bottom:6px">\u26a0 Save your account details</div>
          <div style="font-size:12px;color:var(--text-secondary);margin-bottom:10px">PPQ accounts are anonymous \u2014 <strong>there is no way to recover a lost key</strong>. Copy both values now and store them somewhere safe.</div>
          <label style="font-size:11px;color:var(--text-muted)">API Key</label>
          <div style="font-family:monospace;font-size:11px;word-break:break-all;background:var(--bg-primary);padding:8px;border-radius:6px;border:1px solid var(--border);color:var(--text-primary);user-select:all;cursor:text">${escapeHTML(result.api_key)}</div>
          <label style="font-size:11px;color:var(--text-muted);margin-top:8px;display:block">Credit ID <span style="font-size:10px">(enter at <a href="https://ppq.ai/invite/8f3017cd" target="_blank" rel="noopener" style="color:var(--accent)">ppq.ai</a> to access your account on the web)</span></label>
          <div style="font-family:monospace;font-size:11px;word-break:break-all;background:var(--bg-primary);padding:8px;border-radius:6px;border:1px solid var(--border);color:var(--text-primary);user-select:all;cursor:text">${escapeHTML(result.credit_id)}</div>
          <div style="display:flex;gap:8px;margin-top:8px">
            <button class="import-btn import-btn-primary" style="font-size:12px" data-provider-panel-action="copy-ppq-key-reveal" data-clipboard-text="API Key: ${escapeAttr(result.api_key)}&#10;Credit ID: ${escapeAttr(result.credit_id)}" data-copied-text="\u2713 Copied (clears in 60s)">Copy Both</button>
            <button class="import-btn import-btn-secondary" style="font-size:12px" data-provider-panel-action="dismiss-ppq-key-reveal">${activated ? 'I\u2019ve saved it' : 'Finish without activation'}</button>
          </div>
        </div>
      </div>`;
    }
  }
  catch (e) {
    if (status)
      status.innerHTML = '<span style="color:var(--red)">Failed to create account: ' + escapeHTML(getErrorMessage(e)) + '</span>';
    if (createBtn) {
      createBtn.disabled = false;
      createBtn.textContent = 'Create Account (instant, no signup)';
    }
  }
  _ppqCreating = false;
}
export function dismissPpqKeyReveal() {
  const panel = document.getElementById('ai-provider-panel');
  if (panel)
    panel.innerHTML = renderAIProviderPanel('ppq');
  let cachedModels = [];
  try {
    cachedModels = JSON.parse(localStorage.getItem('labcharts-ppq-models') || '[]');
  }
  catch (e) { }
  if (cachedModels.length)
    renderPpqModelDropdown(cachedModels);
  getPpqBalance().then(function (balance) {
    const el = document.getElementById('ppq-balance');
    if (el && balance != null)
      el.innerHTML = _ppqBalanceHtml(balance);
  });
  showPpqTopup();
  showNotification('Account ready \u2014 top up to start using AI', 'info');
}
export async function handleSavePpqKey() {
  const input = document.getElementById('ppq-key-input');
  const btn = document.getElementById('save-ppq-key-btn');
  const status = document.getElementById('ppq-key-status');
  if (!input || !btn || !status)
    return;
  const key = input.value.trim();
  if (!key) {
    status.innerHTML = '<span style="color:var(--red)">Please enter an API key</span>';
    return;
  }
  btn.disabled = true;
  btn.textContent = 'Validating...';
  const result = await validatePpqKey(key);
  if (result.valid) {
    status.innerHTML = '<span style="color:var(--text-muted)">Connection verified — waiting for activation…</span>';
    if (!await requestProviderActivation('ppq')) {
      status.innerHTML = '<span style="color:var(--text-muted)">Connection verified — AI not activated</span>';
      btn.disabled = false;
      btn.textContent = 'Save & Validate';
      return;
    }
    await savePpqKey(key);
    status.innerHTML = '<span style="color:var(--green)">Connected \u2014 loading models\u2026</span>';
    const models = await fetchPpqModels(key);
    _renderPpqModelsAfterFetch(models);
    const currentStatus = document.getElementById('ppq-key-status');
    if (currentStatus)
      currentStatus.innerHTML = '<span style="color:var(--green)">\u2713 Connected</span>';
    showNotification('PPQ key saved', 'success');
    returnToChatIfOnboarding();
  }
  else {
    status.innerHTML = `<span style="color:var(--red)">${escapeHTML(result.error)}</span>`;
  }
  btn.disabled = false;
  btn.textContent = 'Save & Validate';
}
export async function handleRemovePpqKey() {
  const balance = await getPpqBalance();
  const hasFunds = balance != null && parseFloat(balance) > 0;
  const msg = hasFunds
    ? `This account has $${parseFloat(balance).toFixed(2)} remaining. Removing this key will permanently lose access to those funds unless you\u2019ve saved the key elsewhere.\n\nRemove PPQ key?`
    : 'Remove PPQ key? Make sure you\u2019ve saved it if you want to reuse this account later.';
  if (await showConfirmDialog(msg)) {
    localStorage.removeItem('labcharts-ppq-key');
    updateKeyCache('labcharts-ppq-key', null);
    localStorage.removeItem('labcharts-ppq-models');
    localStorage.removeItem('labcharts-ppq-private-models');
    localStorage.removeItem('labcharts-ppq-model');
    localStorage.removeItem('labcharts-ppq-model-regular');
    localStorage.removeItem('labcharts-ppq-model-private');
    localStorage.removeItem('labcharts-ppq-private-mode');
    localStorage.removeItem('labcharts-ppq-pricing');
    localStorage.removeItem('labcharts-ppq-vision-models');
    localStorage.removeItem('labcharts-ppq-private-vision-models');
    localStorage.removeItem('labcharts-ppq-credit-id');
    showNotification('PPQ key removed', 'info');
    getSettingsModuleFunction('openSettingsModal')?.();
  }
}
export async function refreshPpqBalance() {
  const el = document.getElementById('ppq-balance');
  if (!el)
    return;
  el.textContent = 'Balance: refreshing\u2026';
  const balance = await getPpqBalance();
  if (balance != null)
    el.innerHTML = _ppqBalanceHtml(balance);
  else
    el.textContent = 'Balance: unavailable';
}
const _ppqSvg = {
  lightning: '<svg viewBox="0 0 282 282"><circle cx="141" cy="141" r="141" fill="#7B1AF7"/><path d="M79.76 144.05L173.76 63.05C177.86 60.42 181.76 63.05 179.26 67.55L149.26 126.55H202.76C202.76 126.55 211.26 126.55 202.76 133.55L110.26 215.05C103.76 220.55 99.26 217.55 103.76 209.05L132.76 151.55H79.76C79.76 151.55 71.26 151.55 79.76 144.05Z" fill="#fff"/></svg>',
  btc: '<svg viewBox="0 0 32 32"><circle cx="16" cy="16" r="16" fill="#F7931A"/><path fill="#fff" fill-rule="nonzero" d="M23.189 14.02c.314-2.096-1.283-3.223-3.465-3.975l.708-2.84-1.728-.43-.69 2.765c-.454-.114-.92-.22-1.385-.326l.695-2.783L15.596 6l-.708 2.839c-.376-.086-.746-.17-1.104-.26l.002-.009-2.384-.595-.46 1.846s1.283.294 1.256.312c.7.175.826.638.805 1.006l-.806 3.235c.048.012.11.03.18.057l-.183-.045-1.13 4.532c-.086.212-.303.531-.793.41.018.025-1.256-.313-1.256-.313l-.858 1.978 2.25.561c.418.105.828.215 1.231.318l-.715 2.872 1.727.43.708-2.84c.472.127.93.245 1.378.357l-.706 2.828 1.728.43.715-2.866c2.948.558 5.164.333 6.097-2.333.752-2.146-.037-3.385-1.588-4.192 1.13-.26 1.98-1.003 2.207-2.538zm-3.95 5.538c-.533 2.147-4.148.986-5.32.695l.95-3.805c1.172.293 4.929.872 4.37 3.11zm.535-5.569c-.487 1.953-3.495.96-4.47.717l.86-3.45c.975.243 4.118.696 3.61 2.733z"/></svg>',
  xmr: '<svg viewBox="0 0 32 32"><circle cx="16" cy="16" r="16" fill="#FF6600"/><path fill="#fff" fill-rule="nonzero" d="M15.97 5.235c5.985 0 10.825 4.84 10.825 10.824a11.07 11.07 0 01-.558 3.432h-3.226v-9.094l-7.04 7.04-7.04-7.04v9.094H5.704a11.07 11.07 0 01-.557-3.432c0-5.984 4.84-10.824 10.824-10.824zM14.358 19.02L16 20.635l1.613-1.614 3.051-3.08v5.72h4.547a10.806 10.806 0 01-9.24 5.192c-3.902 0-7.334-2.082-9.24-5.192h4.546v-5.72l3.08 3.08z"/></svg>',
  ltc: '<svg viewBox="0 0 32 32"><circle cx="16" cy="16" r="16" fill="#A6A9AA"/><path fill="#fff" d="M10.427 19.214L9 19.768l.688-2.759 1.444-.58L13.213 8h5.129l-1.519 6.196 1.41-.571-.68 2.75-1.427.571-.848 3.483H23L22.127 24H9.252z"/></svg>',
  liquid: '<svg viewBox="0 0 32 32"><circle cx="16" cy="16" r="16" fill="#0D1437"/><path fill="#22E1C9" d="M16 7c-2.4 3.5-6 7.5-6 11.5C10 21.54 12.69 24 16 24s6-2.46 6-5.5C22 14.5 18.4 10.5 16 7zm0 14.5c-1.93 0-3.5-1.32-3.5-3 0-2.25 2.13-4.82 3.5-6.71 1.37 1.89 3.5 4.46 3.5 6.71 0 1.68-1.57 3-3.5 3z"/></svg>',
};
const PPQ_METHODS = [
  { id: 'btc-lightning', svg: _ppqSvg.lightning, label: 'Lightning', min: 1, amounts: [1, 2, 5, 10] },
  { id: 'btc', svg: _ppqSvg.btc, label: 'Bitcoin', min: 10, amounts: [10, 25, 50, 100] },
  { id: 'xmr', svg: _ppqSvg.xmr, label: 'Monero', min: 5, amounts: [5, 10, 25, 50] },
  { id: 'ltc', svg: _ppqSvg.ltc, label: 'Litecoin', min: 2, amounts: [2, 5, 10, 25] },
  { id: 'lbtc', svg: _ppqSvg.liquid, label: 'Liquid', min: 2, amounts: [2, 5, 10, 25] },
];
let _ppqSelectedMethod = 'btc-lightning';
function _ppqMethodBtn(m, active) {
  return `<button class="${active ? 'ppq-method-btn active' : 'ppq-method-btn'}" data-provider-panel-action="select-ppq-method" data-ppq-method="${escapeAttr(m.id)}"><span class="ppq-method-icon">${m.svg}</span><span class="ppq-method-label">${m.label}</span></button>`;
}
export function showPpqTopup() {
  const area = document.getElementById('ppq-topup-area');
  if (!area)
    return;
  const toggle = document.getElementById('ppq-topup-toggle');
  if (area.style.display !== 'none') {
    area.style.display = 'none';
    if (toggle)
      toggle.textContent = 'Top Up';
    return;
  }
  area.style.display = 'block';
  if (toggle)
    toggle.textContent = 'Close';
  _ppqSelectedMethod = 'btc-lightning';
  if (!document.getElementById('ppq-topup-style')) {
    const style = document.createElement('style');
    style.id = 'ppq-topup-style';
    style.textContent = `.ppq-method-btn{display:flex;flex-direction:column;align-items:center;gap:4px;padding:8px 4px;border-radius:10px;border:2px solid var(--border);background:var(--bg-primary);color:var(--text-muted);cursor:pointer;flex:1;min-width:0;transition:all .15s}
.ppq-method-btn:hover{border-color:var(--text-muted);color:var(--text-primary)}
.ppq-method-btn.active{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 10%,var(--bg-primary));box-shadow:0 0 0 1px var(--accent)}
.ppq-method-btn.active .ppq-method-label{color:var(--text-primary)}
.ppq-method-icon{width:24px;height:24px;display:block}
.ppq-method-icon svg{width:100%;height:100%}
.ppq-method-label{font-size:10px;font-weight:600;white-space:nowrap;letter-spacing:.01em}
.ppq-amt-btn{padding:7px 0;border-radius:8px;border:1px solid var(--border);background:var(--bg-primary);color:var(--text-primary);cursor:pointer;font-size:13px;font-weight:600;flex:1;text-align:center;transition:all .15s}
.ppq-amt-btn:hover{border-color:var(--accent);color:var(--accent)}
@keyframes ppq-pulse{0%,100%{opacity:1}50%{opacity:.3}}`;
    document.head.appendChild(style);
  }
  _renderPpqTopupPicker(area);
}
function _renderPpqTopupPicker(area) {
  const method = PPQ_METHODS.find(function (m) { return m.id === _ppqSelectedMethod; }) || PPQ_METHODS[0];
  area.innerHTML = `<div style="margin-top:8px;padding:12px;background:var(--bg-secondary);border-radius:10px;border:1px solid var(--border)">
    <div style="display:flex;gap:6px;margin-bottom:10px">${PPQ_METHODS.map(function (m) { return _ppqMethodBtn(m, m.id === _ppqSelectedMethod); }).join('')}</div>
    <div style="display:flex;gap:6px">${method.amounts.map(function (v) {
    return '<button class="ppq-amt-btn" data-provider-panel-action="ppq-topup-preset" data-amount="' + v + '">$' + v + '</button>';
  }).join('')}<div id="ppq-custom-slot" style="flex:1;display:flex"><button class="ppq-amt-btn" style="width:100%;color:var(--text-muted)" data-provider-panel-action="show-ppq-custom-input">$\u2026</button></div></div>
    <div style="font-size:10px;color:var(--text-muted);margin-top:5px;text-align:center">$2 is enough for onboarding, a few imports, and chats \u00b7 min $${method.min}</div>
  </div>`;
}
export function selectPpqMethod(methodId) {
  _ppqSelectedMethod = methodId;
  const area = document.getElementById('ppq-topup-area');
  if (area)
    _renderPpqTopupPicker(area);
}
export function ppqShowCustomInput() {
  const slot = document.getElementById('ppq-custom-slot');
  if (!slot)
    return;
  slot.innerHTML = '<input type="text" inputmode="decimal" id="ppq-custom-amount" class="ppq-amt-btn" style="width:100%;text-align:center;cursor:text" placeholder="$">';
  const input = document.getElementById('ppq-custom-amount');
  if (input) {
    input.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        doPpqTopupCustom();
      }
      else if (event.key === 'Escape') {
        event.preventDefault();
        selectPpqMethod(_ppqSelectedMethod);
      }
    });
    input.addEventListener('blur', () => {
      if (input.value.trim())
        doPpqTopupCustom();
    });
    input.focus();
  }
}
export function doPpqTopupCustom() {
  const input = document.getElementById('ppq-custom-amount');
  if (!input)
    return;
  const raw = input.value.replace(/[^0-9.]/g, '');
  const amount = parseFloat(raw);
  const method = PPQ_METHODS.find(function (m) { return m.id === _ppqSelectedMethod; }) || PPQ_METHODS[0];
  if (isNaN(amount) || amount < method.min) {
    showNotification('Minimum amount is $' + method.min, 'error');
    return;
  }
  doPpqTopup(amount);
}
export async function doPpqTopup(amount) {
  const area = document.getElementById('ppq-topup-area');
  if (!area)
    return;
  const method = PPQ_METHODS.find(function (m) { return m.id === _ppqSelectedMethod; }) || PPQ_METHODS[0];
  area.innerHTML = '<div style="margin-top:8px;padding:10px 12px;background:var(--bg-secondary);border-radius:8px;border:1px solid var(--border);font-size:12px;color:var(--text-muted)">Generating invoice\u2026</div>';
  try {
    const result = await createPpqTopup(amount, _ppqSelectedMethod);
    const payString = result.lightning_invoice || result.payment_address || '';
    const invoiceId = result.invoice_id || '';
    const cryptoAmount = result.crypto_amount_due ? parseFloat(result.crypto_amount_due) : null;
    const isLightning = _ppqSelectedMethod === 'btc-lightning';
    let qrSvg = '';
    try {
      const makeQr = await ensureQRCode();
      const qr = makeQr(0, 'L');
      qr.addData(isLightning ? payString.toUpperCase() : payString);
      qr.make();
      qrSvg = qr.createSvgTag({ cellSize: 4, margin: 4, scalable: true });
    }
    catch { /* QR generation failed, show text only */ }
    const walletUri = isLightning ? 'lightning:' + escapeAttr(payString)
      : _ppqSelectedMethod === 'btc' || _ppqSelectedMethod === 'lbtc' ? 'bitcoin:' + escapeAttr(payString)
        : _ppqSelectedMethod === 'ltc' ? 'litecoin:' + escapeAttr(payString)
          : _ppqSelectedMethod === 'xmr' ? 'monero:' + escapeAttr(payString)
            : '#';
    const copyLabel = isLightning ? 'Copy Invoice' : 'Copy Address';
    const detailLabel = isLightning ? 'Show invoice text' : 'Show address';
    const cryptoHint = cryptoAmount ? '<div style="font-size:10px;color:var(--text-muted);margin-top:2px">' + cryptoAmount + '</div>' : '';
    area.innerHTML = `<div style="margin-top:8px;padding:10px 12px;background:var(--bg-secondary);border-radius:8px;border:1px solid var(--border)">
      <div style="display:flex;gap:12px;align-items:flex-start">
        ${qrSvg ? '<div style="flex-shrink:0;background:#fff;padding:6px;border-radius:6px;width:140px;height:140px">' + qrSvg + '</div>' : ''}
        <div style="flex:1;min-width:0">
          <div style="font-size:12px;font-weight:600;color:var(--text-primary);margin-bottom:2px;display:flex;align-items:center;gap:4px"><span style="width:16px;height:16px;display:inline-block">${method.svg}</span> ${method.label} \u2014 $${parseFloat(amount).toFixed(2)}</div>
          ${cryptoHint}
          <div style="display:flex;flex-direction:column;gap:4px;margin-top:6px">
            <button class="import-btn import-btn-primary" style="font-size:11px;padding:4px 10px" data-provider-panel-action="copy-ppq-payment" data-clipboard-text="${escapeAttr(payString)}" data-copied-text="\u2713 Copied!">${copyLabel}</button>
            <a href="${walletUri}" class="import-btn import-btn-secondary" style="font-size:11px;padding:4px 10px;text-decoration:none;text-align:center">Open in Wallet</a>
            <button class="import-btn import-btn-secondary" style="font-size:11px;padding:4px 10px" data-provider-panel-action="cancel-ppq-topup">Cancel</button>
          </div>
          <div id="ppq-topup-status" style="margin-top:6px;font-size:11px;color:var(--text-muted);display:flex;align-items:center;gap:5px"><span id="ppq-topup-dot" style="width:6px;height:6px;border-radius:50%;background:var(--accent);display:inline-block;animation:ppq-pulse 1.5s ease-in-out infinite"></span> <span id="ppq-topup-countdown"></span></div>
        </div>
      </div>
      <details style="margin-top:6px"><summary style="font-size:11px;color:var(--text-muted);cursor:pointer">${detailLabel}</summary>
        <div style="font-family:monospace;font-size:9px;word-break:break-all;background:var(--bg-primary);padding:6px;border-radius:4px;border:1px solid var(--border);color:var(--text-secondary);max-height:80px;overflow-y:auto;user-select:all;cursor:text;margin-top:4px">${escapeHTML(payString)}</div>
      </details>
    </div>`;
    const expiresTs = result.expires_at ? result.expires_at * 1000 : 0;
    _ppqCountdownTimer = setInterval(function () {
      const cdEl = document.getElementById('ppq-topup-countdown');
      if (!cdEl || !expiresTs)
        return;
      const remaining = Math.max(0, Math.floor((expiresTs - Date.now()) / 1000));
      const mins = Math.floor(remaining / 60);
      const secs = remaining % 60;
      cdEl.textContent = remaining > 0
        ? 'Waiting for payment\u2026 ' + mins + ':' + (secs < 10 ? '0' : '') + secs
        : 'Invoice expired';
      if (remaining <= 0)
        clearInterval(_ppqCountdownTimer);
    }, 1000);
    _ppqTopupPollTimer = setInterval(async function () {
      try {
        const status = await checkPpqTopupStatus(invoiceId);
        if (!status)
          return;
        const s = (status.status || '').toLowerCase();
        if (s === 'paid' || s === 'complete' || s === 'settled' || s === 'processing') {
          clearPpqTopupTimers();
          const topupArea = document.getElementById('ppq-topup-area');
          if (topupArea) {
            topupArea.innerHTML = '<div style="margin-top:8px;padding:16px;background:var(--bg-secondary);border-radius:8px;border:1px solid var(--green);text-align:center"><div style="font-size:24px;margin-bottom:6px">\u2713</div><div style="font-size:13px;font-weight:600;color:var(--green)">Payment received!</div><div style="font-size:12px;color:var(--text-muted);margin-top:4px">$' + parseFloat(amount).toFixed(2) + ' added to your balance</div></div>';
          }
          showNotification('Top-up successful!', 'success');
          const balance = await getPpqBalance();
          const balEl = document.getElementById('ppq-balance');
          if (balEl && balance != null)
            balEl.innerHTML = _ppqBalanceHtml(balance);
          setTimeout(function () { returnToChatIfOnboarding(); }, 2000);
        }
        else if (s === 'expired' || s === 'invalid') {
          clearPpqTopupTimers();
          const statusEl = document.getElementById('ppq-topup-status');
          if (statusEl)
            statusEl.innerHTML = '<span style="color:var(--red)">Invoice expired. Try again.</span>';
        }
      }
      catch { /* ignore poll errors */ }
    }, 3000);
  }
  catch (e) {
    area.innerHTML = `<div style="margin-top:8px;padding:10px 12px;background:var(--bg-secondary);border-radius:8px;border:1px solid var(--border);font-size:12px;color:var(--red)">${escapeHTML(getErrorMessage(e))}</div>`;
  }
}
export function cancelPpqTopup() {
  clearPpqTopupTimers();
  const area = document.getElementById('ppq-topup-area');
  if (area)
    area.style.display = 'none';
}

/* ─────────────────────────────────────────────────────────
   Wearable strip (dashboard section between Supplements and Key Trends)
   ───────────────────────────────────────────────────────── */
.wearable-strip {
  margin: 20px 0 8px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 14px 16px 12px;
  /* On mobile the chat + import FABs sit at the bottom-right and overlap the
     last strip card. Reserve enough bottom margin so the FABs don't obscure
     readings. (Desktop FAB is smaller and the strip isn't bottom-anchored.) */
  box-shadow: var(--shadow);
}
.wearable-strip-stub {
  border-style: dashed;
}
.wearable-strip-stub-body {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
}
.wearable-strip-stub-text {
  flex: 1; min-width: 200px; font-size: 13px; line-height: 1.5;
  color: var(--text-secondary);
}
.wearable-strip-stub-text strong { color: var(--text-primary); }
.wearable-strip-stub-brands {
  display: block; margin-top: 2px; font-size: 11px; color: var(--text-muted);
}
.wearable-strip-stub-actions {
  display: flex; gap: 6px; align-items: center;
}
.wearable-strip-stub-cta {
  background: var(--accent); color: var(--on-accent); border: none; padding: 6px 14px;
  border-radius: 6px; font-size: 13px; font-weight: 500; cursor: pointer;
}
.wearable-strip-stub-cta:hover { filter: brightness(1.08); }
.wearable-strip-stub-dismiss {
  background: none; border: none; color: var(--text-muted); cursor: pointer;
  font-size: 18px; line-height: 1; padding: 4px 8px; border-radius: 4px;
}
.wearable-strip-stub-dismiss:hover { background: var(--bg-secondary); color: var(--text-primary); }
@media (max-width: 600px) {
  .wearable-strip {
    margin-bottom: 80px; /* room for chat FAB + import FAB stacked */
  }
}
.wearable-strip-header {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px; margin-bottom: 10px; cursor: pointer;
  user-select: none;
}
.wearable-strip-title {
  display: flex; align-items: center; gap: 8px;
  font-size: 15px; font-weight: 600; color: var(--text-primary);
}
.wearable-strip-icon { font-size: 16px; color: var(--accent); letter-spacing: 0.04em; }
.wearable-source-label {
  font-size: 12px; font-weight: 500; color: var(--text-muted);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, monospace);
}
.wearable-strip-demo-pill {
  font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em;
  background: var(--yellow-bg); color: var(--yellow);
  padding: 2px 7px; border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--yellow) 25%, transparent);
  cursor: pointer; transition: filter 0.15s;
}
.wearable-strip-demo-pill:hover { filter: brightness(1.1); }
/* Reorder-mode banner — visible cue that the strip is in arrange-mode so the
   user knows the ◀ ▶ arrows are intentional, not accidental. */
.wearable-strip-reorder-pill {
  font-size: 11px; font-weight: 600; letter-spacing: 0.02em;
  background: var(--accent-fill); color: var(--accent);
  padding: 3px 9px; border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--accent) 35%, transparent);
  white-space: nowrap;
}
/* Grid tint while reordering — a subtle accent so it's obviously different. */
.wearable-card-grid-reorder {
  background: color-mix(in srgb, var(--accent) 4%, transparent);
  border-radius: 14px;
  padding: 8px;
  margin: -8px;
  outline: 1px dashed color-mix(in srgb, var(--accent) 25%, transparent);
}
/* Apple Health export how-to disclosure — long instructions live behind a
   "How to export from your iPhone" summary so the dropzone is the headline. */
.apple-health-howto { margin: 6px 0 8px; cursor: pointer; }
.apple-health-howto > summary {
  font-weight: 500; color: var(--text-primary); padding: 4px 0;
  list-style: none;
}
.apple-health-howto > summary::-webkit-details-marker { display: none; }
.apple-health-howto > summary::before {
  content: "▸ "; color: var(--text-muted);
}
.apple-health-howto[open] > summary::before { content: "▾ "; }
.apple-health-howto ol {
  margin: 6px 0 8px 18px; padding: 0; color: var(--text-muted);
}
.apple-health-howto ol li { margin-bottom: 4px; }
.apple-health-privacy { font-style: italic; color: var(--text-muted); margin: 6px 0 0; }

.wearable-strip-meta {
  display: flex; align-items: center; gap: 12px;
  font-size: 12px; color: var(--text-muted);
}
.wearable-strip-sync {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 4px 10px 4px 8px; border-radius: 999px;
  border: 1px solid var(--border); background: transparent;
  color: var(--text-secondary); font: inherit; font-size: 11px; font-weight: 500;
  cursor: pointer; transition: all 0.15s ease; line-height: 1;
}
.wearable-strip-sync:hover:not(:disabled) {
  border-color: var(--accent); color: var(--accent); background: var(--bg-secondary);
}
.wearable-strip-sync:disabled { opacity: 0.7; cursor: progress; }
.wearable-strip-sync-icon { transition: transform 0.2s ease; flex-shrink: 0; }
.wearable-strip-sync.is-syncing .wearable-strip-sync-icon {
  animation: wearable-spin 0.9s linear infinite;
}
@keyframes wearable-spin { to { transform: rotate(360deg); } }
.wearable-collapse-arrow {
  display: inline-block; transition: transform 0.18s ease;
  color: var(--text-muted); font-size: 14px;
  background: none; border: 0; padding: 0; cursor: pointer; line-height: 1;
}
.wearable-collapse-arrow:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 4px; }
.wearable-collapse-arrow.collapsed { transform: rotate(-90deg); }

.wearable-card-grid {
  display: grid;
  /* auto-fit so the grid stays even no matter how many cards the adapter
     registry produces (4 for Oura basics, 8-9 with full scopes, more when
     WHOOP/Apple Health join). Cards want ~220px min; the row refills across
     the available width without leaving half-empty tail rows. */
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 10px;
}
.wearable-card-grid.hidden { display: none; }

.wearable-card {
  background: var(--bg-primary);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 12px 8px;
  display: flex; flex-direction: column; gap: 6px;
  cursor: pointer;
  transition: border-color 0.15s ease, transform 0.15s ease;
  min-width: 0;
}
.wearable-card:hover {
  border-color: var(--accent);
  transform: translateY(-1px);
}
.wearable-card:focus-visible {
  outline: 2px solid var(--accent); outline-offset: 2px;
}

/* Empty-state cards for manual-capable metrics with no data yet */
.wearable-card-empty {
  border-style: dashed;
  opacity: 0.82;
}
.wearable-card-empty:hover { opacity: 1; }
.wearable-value-row-empty { justify-content: flex-start; }
.wearable-value-dash { color: var(--text-muted); font-weight: 400; }
.wearable-empty-cta {
  font-size: 11px; color: var(--accent); font-weight: 600;
  letter-spacing: 0.02em;
}

/* Inline manual-log form (opens in-place when empty card is clicked) */
.wearable-log-form { display: flex; flex-direction: column; gap: 6px; padding-top: 2px; }
.wearable-log-input {
  width: 100%; padding: 6px 8px; font-size: 15px; font-weight: 600;
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: 6px; color: var(--text-primary); box-sizing: border-box;
}
.wearable-log-input:focus {
  outline: none; border-color: var(--accent); background: var(--bg-primary);
}
.wearable-log-bp-row { display: flex; align-items: center; gap: 4px; }
.wearable-log-bp { min-width: 0; flex: 1; text-align: center; }
.wearable-log-sep { color: var(--text-muted); font-weight: 600; }
.wearable-log-pulse-optional { font-size: 12px; padding: 4px 8px; }
.wearable-log-row { display: flex; align-items: center; gap: 4px; }
.wearable-log-date {
  flex: 1; min-width: 0; padding: 4px 6px; font-size: 11px;
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: 6px; color: var(--text-muted);
  color-scheme: dark;
}
[data-theme="light"] .wearable-log-date { color-scheme: light; }
.wearable-log-save {
  padding: 4px 10px; font-size: 11px; font-weight: 600;
  background: var(--accent); color: #fff; border: 0; border-radius: 6px;
  cursor: pointer;
}
.wearable-log-save:hover { filter: brightness(1.1); }
.wearable-log-cancel {
  padding: 4px 8px; font-size: 13px; background: transparent;
  border: 0; color: var(--text-muted); cursor: pointer; line-height: 1;
}
.wearable-log-cancel:hover { color: var(--text-primary); }

/* Optional context-tag chips on the inline log form (BP / RHR). Toggle-
   selectable. Purely informational — a post-workout BP reading tells a
   different story than a resting one, even when the numbers match. */
.wearable-log-tags { display: flex; flex-wrap: wrap; gap: 4px; padding: 2px 0; }
.wearable-log-chip {
  font-size: 10px; padding: 3px 7px; line-height: 1.2;
  background: transparent; color: var(--text-muted);
  border: 1px solid var(--border); border-radius: 10px;
  cursor: pointer; transition: all 0.12s ease;
}
.wearable-log-chip:hover { color: var(--text-primary); border-color: var(--text-muted); }
.wearable-log-chip.active {
  background: var(--accent-faded, rgba(99,102,241,0.18));
  color: var(--accent);
  border-color: var(--accent);
  font-weight: 600;
}
.wearable-log-note {
  width: 100%; min-height: 38px; padding: 6px 8px;
  background: var(--bg-primary); color: var(--text-primary);
  border: 1px solid var(--border); border-radius: 6px;
  font-size: 12px; font-family: inherit; resize: vertical; box-sizing: border-box;
}
.wearable-log-note:focus { border-color: var(--accent); outline: none; }
.wearable-log-note::placeholder { color: var(--text-muted); }

/* Manual entries list in the detail modal — per-row delete + add form */
.wearable-manual-entries {
  margin-top: 14px; padding-top: 12px;
  border-top: 1px solid var(--border);
}
.wearable-manual-entries-compact {
  text-align: right;
}
.wearable-manual-entries-compact .wearable-manual-add-btn {
  font-size: 12px; opacity: 0.85;
}
.wearable-manual-entries-head {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 8px;
}
.wearable-manual-entries-title {
  font-size: 13px; font-weight: 600; color: var(--text-primary);
}
.wearable-manual-entries-count {
  display: inline-block; margin-left: 6px; padding: 1px 6px;
  font-size: 10px; font-weight: 500; color: var(--text-muted);
  background: var(--bg-tertiary, rgba(128,128,128,0.08)); border-radius: 8px;
}
.wearable-manual-add-btn {
  padding: 4px 10px; font-size: 11px; font-weight: 600;
  background: transparent; color: var(--accent);
  border: 1px solid var(--accent); border-radius: 6px;
  cursor: pointer;
}
.wearable-manual-add-btn:hover { background: var(--accent-faded, rgba(99,102,241,0.12)); }
.wearable-manual-entries-empty {
  font-size: 12px; color: var(--text-muted); padding: 6px 0;
}
.wearable-manual-entries-list {
  list-style: none; padding: 0; margin: 0;
  max-height: 240px; overflow-y: auto;
  border: 1px solid var(--border); border-radius: 6px;
}
.wearable-manual-entry {
  display: flex; align-items: center; gap: 10px;
  padding: 6px 10px; font-size: 12px;
  border-bottom: 1px solid var(--border);
}
.wearable-manual-entry:last-child { border-bottom: 0; }
.wearable-manual-entry-date { color: var(--text-muted); min-width: 84px; font-variant-numeric: tabular-nums; }
.wearable-manual-entry-val { font-weight: 600; font-variant-numeric: tabular-nums; }
.wearable-manual-entry-unit { font-weight: 400; color: var(--text-muted); font-size: 11px; }
.wearable-manual-entry-tags { display: inline-flex; gap: 3px; flex-wrap: wrap; }
.wearable-manual-entry-tag {
  font-size: 9px; padding: 1px 5px; border-radius: 8px;
  background: var(--bg-tertiary, rgba(128,128,128,0.08));
  color: var(--text-muted); text-transform: lowercase;
}
.wearable-manual-entry-del {
  margin-left: auto; padding: 2px 7px; font-size: 13px; line-height: 1;
  background: transparent; border: 0; color: var(--text-muted);
  cursor: pointer; border-radius: 4px;
}
.wearable-manual-entry-del:hover { color: var(--red, #ef4444); background: var(--bg-tertiary, rgba(239,68,68,0.08)); }
.wearable-manual-entry.has-note { flex-wrap: wrap; }
.wearable-manual-entry-note {
  flex-basis: 100%; font-size: 11px; color: var(--text-secondary);
  font-style: italic; margin-top: 2px; padding-left: 0; line-height: 1.35;
  word-break: break-word;
}
.wearable-manual-add-form {
  display: flex; align-items: center; gap: 6px; flex-wrap: wrap;
  padding: 8px 10px; margin-bottom: 8px;
  background: var(--bg-tertiary, rgba(128,128,128,0.06)); border-radius: 6px;
}
.wearable-manual-add-form .wearable-log-input { max-width: 110px; }
.wearable-manual-add-form .wearable-log-date { max-width: 140px; }
.wearable-manual-add-form-bp .wearable-log-bp-row { gap: 2px; }

/* Reorder mode — tiny ⇄ button in the strip header toggles it; cards gain
   ◀ ▶ arrows overlaid on their top-right. Works on mouse + touch without
   drag-and-drop, so no vendored sortable library needed. */
.wearable-strip-reorder {
  padding: 3px 9px; font-size: 11px; font-weight: 600;
  background: transparent; border: 1px solid var(--border); border-radius: 6px;
  color: var(--text-muted); cursor: pointer;
  display: inline-flex; align-items: center; gap: 4px;
  transition: all 0.12s ease;
}
.wearable-strip-reorder:hover { color: var(--text-primary); border-color: var(--text-muted); }
.wearable-strip-reorder.active {
  background: var(--accent); color: #fff; border-color: var(--accent);
}
.wearable-card-reorder-wrap {
  position: relative; display: flex; flex-direction: column;
  min-width: 0;
}
.wearable-card-reorder-wrap > .wearable-card {
  cursor: default;
  pointer-events: none; /* suppress clicks/badges on underlying card while reordering */
  opacity: 0.92;
}
.wearable-card-reorder-wrap > .wearable-card:hover {
  border-color: var(--border); transform: none; /* cancel hover-lift */
}
.wearable-reorder-arrows {
  position: absolute; top: 6px; right: 6px;
  display: flex; gap: 2px; z-index: 2;
}
.wearable-reorder-arrow {
  padding: 2px 6px; font-size: 11px; line-height: 1;
  background: var(--bg-secondary); color: var(--text-primary);
  border: 1px solid var(--border); border-radius: 4px;
  cursor: pointer;
}
.wearable-reorder-arrow:hover:not(:disabled) {
  background: var(--accent); color: #fff; border-color: var(--accent);
}
.wearable-reorder-arrow:disabled { opacity: 0.35; cursor: not-allowed; }

.wearable-card-top {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
}
.wearable-metric-name {
  font-size: 12px; font-weight: 600; color: var(--text-secondary);
  text-transform: uppercase; letter-spacing: 0.04em;
  display: flex; align-items: baseline; gap: 4px; min-width: 0;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.wearable-metric-sub {
  font-size: 10px; font-weight: 500; color: var(--text-muted);
  text-transform: none; letter-spacing: 0;
}
.wearable-delta {
  font-size: 11px; font-weight: 600;
  padding: 1px 6px; border-radius: 8px; white-space: nowrap;
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, monospace);
}
.wearable-delta.delta-good { background: var(--green-bg); color: var(--green); }
.wearable-delta.delta-bad  { background: var(--red-bg);   color: var(--red); }
.wearable-delta.delta-flat { background: var(--neutral-soft-bg); color: var(--text-muted); }

.wearable-value-row {
  display: flex; align-items: baseline; gap: 4px; flex-wrap: wrap;
  min-height: 24px;
}
.wearable-value {
  font-size: 22px; font-weight: 700; color: var(--text-primary);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.wearable-unit {
  font-size: 12px; color: var(--text-muted); font-weight: 500;
}
/* Tight unit hugs the value with no separating space — used for "/5" and
   similar prefix-slash units so "1/5" reads as one token, not "1 /5". */
.wearable-unit-tight {
  margin-left: 0 !important;
}
.wearable-value-row .wearable-unit-tight {
  /* Value-row default has flex gap; tight unit cancels it. */
  margin-left: -4px !important;
}
.wearable-baseline {
  margin-left: auto; font-size: 10px; color: var(--text-muted);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, monospace);
  white-space: nowrap;
}
.wearable-staleness {
  flex-basis: 100%; margin-top: 2px; font-size: 10px;
  color: var(--text-muted); font-style: italic; white-space: nowrap;
  cursor: help;
}
/* On narrow strip cards the baseline + staleness chip stack as two muted
   grey lines below the value, which reads as a paragraph blob. Hide the
   baseline annotation when the staleness hint is present and viewport is
   tight; the staleness chip already implies "this isn't your most recent
   typical reading" and the detail modal carries the precise baseline. */
@media (max-width: 600px) {
  .wearable-card .wearable-staleness ~ .wearable-baseline,
  .wearable-card:has(.wearable-staleness) .wearable-baseline { display: none; }
}

.wearable-sparkline {
  width: 100%; height: 32px; display: block;
  color: var(--text-muted);
}
.wearable-sparkline .spark-baseline {
  stroke: currentColor; stroke-opacity: 0.25;
  stroke-dasharray: 2 3; stroke-width: 0.5;
}
.wearable-sparkline .spark-line {
  fill: none; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}
.wearable-sparkline .spark-last { stroke: var(--bg-card); stroke-width: 0.8; }
.wearable-sparkline.spark-bad .spark-line,
.wearable-sparkline.spark-bad .spark-last { stroke: var(--red); fill: var(--red); }
.wearable-sparkline.spark-good .spark-line,
.wearable-sparkline.spark-good .spark-last { stroke: var(--green); fill: var(--green); }
.wearable-sparkline.spark-neutral .spark-line,
.wearable-sparkline.spark-neutral .spark-last { stroke: var(--accent); fill: var(--accent); }

.wearable-card-bottom {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  min-height: 18px;
}
.wearable-trend-pill {
  font-size: 10px; font-weight: 500; color: var(--text-muted);
  padding: 1px 6px; border-radius: 6px;
  background: var(--neutral-soft-bg);
  text-transform: none; letter-spacing: 0;
  white-space: nowrap; flex-shrink: 0;
}
.wearable-trend-bad       { color: var(--red);   background: var(--red-bg); }
.wearable-trend-good      { color: var(--green); background: var(--green-bg); }
.wearable-trend-improving { color: var(--green); background: var(--green-bg); }
.wearable-trend-flat      { color: var(--text-muted); background: var(--neutral-soft-bg); }
.wearable-source-badge {
  font-size: 10px; font-weight: 600; color: var(--text-muted);
  letter-spacing: 0.02em;
  padding: 1px 5px; border-radius: 4px;
  background: var(--neutral-soft-bg);
  min-width: 0; max-width: 100%;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
/* Badge keeps title-case at every width — earlier the all-caps desktop
   variant read as shouty next to the lowercase metric labels. */
@media (max-width: 600px) {
  .wearable-source-badge {
    font-size: 10px;
    text-transform: none;
    letter-spacing: 0.01em;
  }
}

.wearable-strip-footer {
  margin-top: 10px; padding-top: 8px;
  border-top: 1px dashed var(--border);
  font-size: 11px; color: var(--text-muted); font-style: italic;
  display: flex; flex-wrap: wrap; gap: 4px 14px;
}
.wearable-strip-footer.hidden { display: none; }
.wearable-strip-footer-note { display: inline-block; }
.wearable-strip-footer-note + .wearable-strip-footer-note::before {
  content: "·"; margin-right: 14px; opacity: 0.5;
}

/* ── Wearable detail modal ── */
.wearable-detail-range { margin: 10px 0 4px; justify-content: flex-start; }
.wearable-detail-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 10px;
  margin-top: 16px;
}
.wearable-detail-stat {
  background: var(--bg-primary);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 12px;
  display: flex; flex-direction: column; gap: 2px;
}
.wearable-detail-stat-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  font-weight: 600;
}
.wearable-detail-stat-val {
  font-size: 18px;
  font-weight: 600;
  color: var(--text-primary);
}
.wearable-detail-stat-sub {
  font-size: 11px;
  color: var(--text-secondary);
  opacity: 0.75;
}
.wearable-detail-empty {
  margin-top: 14px;
  padding: 12px 14px;
  background: var(--bg-primary);
  border: 1px dashed var(--border);
  border-radius: 8px;
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* Settings — wearable adapter list (Slack/Notion-style integrations row).
   Each vendor gets one row; connected vendors expand a details drawer. */
.wearable-visibility-row {
  margin-bottom: 16px;
}
.wearable-sources-intro {
  padding: 15px 17px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--accent) 7%, transparent), transparent 62%),
    var(--bg-card);
}
.wearable-sources-heading .settings-section-title {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 650;
  line-height: 1.4;
}
.wearable-sources-heading p,
.wearable-sources-privacy p {
  margin: 5px 0 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.55;
}
.wearable-beta-label {
  padding: 2px 7px;
  border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--border));
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 9%, transparent);
  color: var(--accent);
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .07em;
  line-height: 1.4;
  text-transform: uppercase;
}
.wearable-sources-privacy {
  margin-top: 11px;
  padding-top: 10px;
  border-top: 1px solid var(--border);
}
.wearable-sources-privacy summary {
  width: fit-content;
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
}
.wearable-sources-privacy summary:hover { color: var(--accent); }
.wearable-sources-privacy p { max-width: 76ch; }
.wearable-relay-consent-summary > div { line-height: 1.45; }
.wearables-adapter-groups {
  display: flex;
  flex-direction: column;
  gap: 20px;
  margin-top: 16px;
}
.wearables-adapter-group-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  padding: 0 2px;
}
.wearables-adapter-group-title {
  margin: 0;
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 650;
  line-height: 1.4;
}
.wearables-adapter-group-hint {
  margin: 0;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.4;
  text-align: right;
}
.wearables-adapter-list {
  display: flex;
  flex-direction: column;
  margin-top: 8px;
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  background: var(--bg-primary);
}
@media (max-width: 600px) {
  .wearables-adapter-group-heading {
    display: block;
  }
  .wearables-adapter-group-hint {
    margin-top: 2px;
    text-align: left;
  }
}
.wearable-row {
  border-bottom: 1px solid var(--border);
  transition: background 0.12s ease;
}
.wearable-row:last-child { border-bottom: 0; }
.wearable-row:hover { background: rgba(255,255,255,0.02); }
[data-theme="light"] .wearable-row:hover { background: rgba(0,0,0,0.02); }
.wearable-row[open] { background: var(--bg-secondary); }
.wearable-row-summary {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  cursor: pointer;
  user-select: none;
  list-style: none;
  min-height: 56px;
}
.wearable-row-summary::-webkit-details-marker { display: none; }
.wearable-row-summary-flat {
  cursor: default;
}
.wearable-row-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  flex-shrink: 0;
}
.wearable-row-status {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  color: var(--text-muted);
  flex: 1;
  min-width: 0;
}
.wearable-row-status-detail { color: var(--text-muted); }
.wearable-row-status-separator { color: var(--text-muted); }
.wearable-row-status-ok      { color: var(--green); }
.wearable-row-status-bad     { color: var(--red); }
.wearable-row-status-pending { color: var(--text-muted); font-style: italic; }
.wearable-row-status-muted   { color: var(--text-muted); }
.wearable-row-action {
  display: inline-flex;
  align-items: center;
  margin-left: auto;
  flex-shrink: 0;
}
.wearable-row-link {
  font-size: 12px;
  color: var(--text-muted);
  text-decoration: none;
  padding: 4px 8px;
  border-radius: 6px;
}
.wearable-row-link:hover { color: var(--accent); background: var(--bg-secondary); }
.wearable-row-chevron {
  color: var(--text-muted);
  font-size: 14px;
  transition: transform 0.18s ease;
  display: inline-block;
  padding: 0 4px;
}
.wearable-row[open] .wearable-row-chevron { transform: rotate(180deg); }
.wearable-row-detail {
  padding: 4px 16px 16px 48px;  /* Indent past the icon column */
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-top: 1px solid var(--border);
  background: var(--bg-primary);
}
/* Right-side action button — plain accent pill, uniform across vendors.
   Vendor brand identity sits on the left (mark + name); the right side
   speaks pure action language so the column reads as one consistent
   "what does this row let me do?" affordance. */
.wearable-action-row-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 16px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
  line-height: 1;
  white-space: nowrap;
  min-width: 88px;
  justify-content: center;
}
.wearable-action-row-btn:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--accent);
  background: var(--bg-secondary);
}
.wearable-action-row-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

@media (max-width: 600px) {
  .wearable-sources-intro { padding: 14px; }
  .wearable-row-summary { gap: 9px; padding-inline: 12px; }
  .wearable-row-status-detail,
  .wearable-row-status-separator { display: none; }
}

/* Legacy chip styles — preserved for any external reuse but no longer
   applied by the settings panel. Kept lean. */
.wearable-adapter-chip {
  font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em;
  padding: 2px 8px; border-radius: 8px;
}
.wearable-adapter-chip-off { background: var(--neutral-soft-bg); color: var(--text-muted); }
.wearable-adapter-chip-ok  { background: var(--green-bg); color: var(--green); }
.wearable-adapter-chip-bad { background: var(--red-bg); color: var(--red); }
/* ── Apple Health file import dropzone ── */
.apple-health-dropzone {
  margin-top: 10px;
  padding: 18px 14px;
  border: 1px dashed var(--border);
  border-radius: 8px;
  background: var(--bg-primary);
  text-align: center;
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease;
}
.apple-health-dropzone:hover,
.apple-health-dropzone.drag-over {
  border-color: var(--accent);
  background: var(--bg-secondary);
}
.apple-health-dropzone-icon { font-size: 22px; margin-bottom: 6px; }
.apple-health-dropzone-text { font-size: 12px; color: var(--text-secondary); }
.apple-health-dropzone-text code {
  background: var(--bg-secondary);
  padding: 1px 5px;
  border-radius: 3px;
  font-size: 11px;
}
.apple-health-progress {
  margin-top: 10px;
  display: flex; flex-direction: column; gap: 4px;
}
.apple-health-progress-bar {
  height: 4px;
  background: var(--bg-secondary);
  border-radius: 2px;
  overflow: hidden;
}
.apple-health-progress-fill {
  height: 100%;
  background: var(--accent);
  width: 0%;
  transition: width 0.2s ease;
}
.apple-health-progress-text { font-size: 11px; color: var(--text-secondary); }

/* ── Source badge + picker (multi-source override) ── */
.wearable-source-badge-btn {
  border: 0;
  cursor: pointer;
  font: inherit;
}
.wearable-source-badge-btn:hover {
  text-decoration: underline;
}
.wearable-source-picker {
  background: var(--bg-elevated, var(--bg-primary));
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.3);
  padding: 6px;
  min-width: 160px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.wearable-source-picker-head {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  padding: 6px 10px 4px;
}
.wearable-source-picker-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 10px;
  border: 0;
  background: transparent;
  color: var(--text-primary);
  font: inherit;
  font-size: 13px;
  cursor: pointer;
  border-radius: 6px;
  text-align: left;
}
.wearable-source-picker-item:hover {
  background: var(--bg-secondary);
}
.wearable-source-picker-item.selected {
  background: var(--bg-secondary);
  color: var(--accent);
}
.wearable-source-picker-check {
  color: var(--accent);
  font-weight: 600;
}
.wearable-source-picker-auto {
  border-top: 1px solid var(--border);
  margin-top: 4px;
  padding-top: 10px;
  font-style: italic;
  opacity: 0.85;
}

.wearable-adapter-chip-beta {
  background: linear-gradient(90deg, color-mix(in srgb, var(--purple) 18%, transparent), color-mix(in srgb, var(--accent) 18%, transparent));
  color: var(--purple);
  border: 1px solid color-mix(in srgb, var(--purple) 35%, transparent);
  font-size: 9px;
  letter-spacing: 0.08em;
  margin-left: 4px;
}
.wearable-adapter-body { display: flex; flex-direction: column; gap: 8px; }
.wearable-adapter-hint { font-size: 12px; color: var(--text-muted); margin: 0; }
.wearable-adapter-hint a { color: var(--accent); text-decoration: none; }
.wearable-adapter-hint a:hover { text-decoration: underline; }
.wearable-adapter-input {
  width: 100%; padding: 8px 10px; border-radius: 6px;
  border: 1px solid var(--border); background: var(--bg-card); color: var(--text-primary);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, monospace); font-size: 13px;
}
.wearable-adapter-actions {
  display: flex; gap: 6px; flex-wrap: wrap;
}
.wearable-adapter-identity {
  font-size: 13px; color: var(--text-primary); font-weight: 500;
}
.wearable-adapter-meta {
  font-size: 11px; color: var(--text-muted);
}
.wearable-adapter-note {
  font-size: 12px; color: var(--text-muted); font-style: italic; margin: 0;
}

/* ── Vendor form-factor icon (settings cards + Connect buttons) ── */
.wearable-vendor-icon {
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--text-secondary);
  flex-shrink: 0;
}
.wearable-adapter-name {
  display: inline-flex; align-items: center; gap: 8px;
}
.wearable-adapter-card.is-connected .wearable-vendor-icon {
  color: var(--accent);
}
.wearable-adapter-card.is-connected {
  border-color: color-mix(in srgb, var(--accent) 25%, transparent);
}

/* ── Unified adapter action button (replaces ad-hoc ctx-btn-option overrides) ── */
.wearable-action {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 7px 14px; border-radius: 999px;
  border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary);
  font: inherit; font-size: 12px; font-weight: 500;
  cursor: pointer; transition: all 0.15s ease; line-height: 1;
  white-space: nowrap;
}
.wearable-action:hover:not(:disabled) {
  border-color: var(--accent); color: var(--accent); background: var(--bg-secondary);
}
.wearable-action:disabled { opacity: 0.7; cursor: progress; }
.wearable-action-secondary {
  /* "Re-sync 90 days" / disconnect-style actions — heavier than incremental
     "Sync." Use a softer styling so a routine sync isn't visually identical
     to a 90-day refetch that hits rate limits and takes 30s+. */
  font-weight: 400; opacity: 0.8;
}
.wearable-action-secondary:hover:not(:disabled) {
  opacity: 1;
}
.wearable-action-hint {
  font-size: 10px; color: var(--text-muted); margin-left: 4px;
}
.wearable-action-icon { flex-shrink: 0; transition: transform 0.2s ease; }
.wearable-action.is-syncing .wearable-action-icon {
  animation: wearable-spin 0.9s linear infinite;
}
.wearable-action-primary {
  background: var(--accent-gradient);
  border-color: transparent;
  color: white;
}
.wearable-action-primary:hover:not(:disabled) {
  filter: brightness(1.08);
  border-color: transparent; color: white; background: var(--accent-gradient);
}
.wearable-action-danger {
  color: var(--text-muted);
}
.wearable-action-danger:hover:not(:disabled) {
  border-color: var(--red); color: var(--red); background: var(--red-bg);
}
.wearable-action-connect {
  padding: 7px 18px;
  font-size: 13px;
}
.wearable-action-connect .wearable-vendor-icon {
  color: rgba(255, 255, 255, 0.95);
}
/* Vendor-branded Connect button — uses --brand-color from inline style.
   Phase 2b: official sign-in graphics (rendered via .wearable-action-signin)
   take precedence over this; this variant is the middle tier between the
   generic accent pill and a fully vendor-supplied button. */
.wearable-action-branded {
  background: var(--brand-color);
  border-color: transparent;
  color: white;
  /* Subtle brand-coloured ring on focus for accessibility. */
}
.wearable-action-branded:hover:not(:disabled) {
  background: var(--brand-color);
  filter: brightness(1.1);
  border-color: transparent;
  color: white;
}
.wearable-action-branded:focus-visible {
  outline: 2px solid var(--brand-color);
  outline-offset: 2px;
}
/* Official vendor Sign-in-with-X graphic — render unmodified. Browsers
   handle the click target; we only constrain max width to keep layout
   sane. */
.wearable-action-signin {
  border: 0;
  background: transparent;
  padding: 0;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  line-height: 0;
}
.wearable-action-signin img {
  height: 36px;
  width: auto;
  max-width: 220px;
  display: block;
}
.wearable-action-signin:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}
/* Wordmark on a brand-coloured pill — used when the official asset is just
   the vendor wordmark (not a full badge). The pill provides the corporate
   colour; the wordmark provides the identity. */
.wearable-action-signin-branded {
  background: var(--brand-color);
  border-radius: 999px;
  padding: 9px 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: filter 0.15s ease;
}
.wearable-action-signin-branded:hover:not(:disabled) {
  filter: brightness(1.1);
}
.wearable-action-signin-branded img {
  height: 18px;
  width: auto;
  max-width: 160px;
}
/* Wordmark on accent pill — when the vendor's guideline is monochrome
   (e.g. Oura) so we don't apply a brand colour. */
.wearable-action-signin-accent {
  background: var(--accent-gradient);
  border-radius: 999px;
  padding: 9px 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: filter 0.15s ease;
}
.wearable-action-signin-accent:hover:not(:disabled) {
  filter: brightness(1.1);
}
.wearable-action-signin-accent img {
  height: 18px;
  width: auto;
  max-width: 160px;
}
/* Vendor mark — uses CSS mask so the SVG silhouette inherits currentColor
   from its parent. --mark-url and --mark-size are set inline by
   brandMarkMono(). Same mark file renders white inside a coloured button,
   muted next to a card heading, accent-coloured on a connected card. */
.wearable-vendor-mark {
  display: inline-block;
  width: var(--mark-size, 18px);
  height: var(--mark-size, 18px);
  background-color: currentColor;
  -webkit-mask: var(--mark-url) center / contain no-repeat;
  mask: var(--mark-url) center / contain no-repeat;
  flex-shrink: 0;
}
/* Vendor logo IMG (full-colour brand asset on the left side of the row).
   Fixed height so the row stays a consistent visual rhythm; width follows
   the SVG's intrinsic aspect ratio. Capped at 90px wide so very long
   wordmarks (Ultrahuman, Polar) don't push the vendor name off-screen. */
.wearable-vendor-icon-img {
  display: block;
  flex-shrink: 0;
  height: 18px;
  width: auto;
  max-width: 90px;
  object-fit: contain;
  object-position: left center;
}
/* Ghost link-style action (e.g. "How?" disclosure) — no border, uses accent */
.wearable-action-link {
  border: 0;
  padding: 7px 10px;
  color: var(--text-muted);
  background: transparent;
}
.wearable-action-link:hover:not(:disabled) {
  color: var(--accent);
  background: transparent;
  border-color: transparent;
}
/* Compact disconnected body — drops the padding/gap weight that made
   Apple Health + 5 OAuth cards a vertical wall of repetition. */
.wearable-adapter-body-compact {
  gap: 10px;
}
.wearable-adapter-hint-warn { color: var(--red); }
.wearable-adapter-hint-pending {
  font-size: 12px;
  color: var(--text-muted);
  font-style: italic;
}
/* Expandable "how does Apple Health file import work?" explainer.
   Collapsed by default; expanded when card gets .show-help. */
.wearable-adapter-help {
  display: none;
  padding-top: 8px;
  border-top: 1px dashed var(--border);
  margin-top: 4px;
}
.wearable-adapter-card.show-help .wearable-adapter-help { display: block; }
.wearable-detail-emf-hint { font-size: 12px; color: var(--text-secondary); margin-top: 14px; padding: 8px 10px; background: rgba(99, 102, 241, 0.05); border-left: 3px solid var(--accent); border-radius: 0 var(--radius) var(--radius) 0; line-height: 1.5; }
.wearable-detail-emf-hint a { color: var(--accent); text-decoration: none; font-weight: 500; }
.wearable-detail-emf-hint a:hover { text-decoration: underline; }

/* Responsive: 2 cols → 1 col */
@media (max-width: 900px) {
  .wearable-card-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 520px) {
  .wearable-card-grid { grid-template-columns: 1fr; gap: 8px; }
  .wearable-strip { padding: 12px 12px 10px; }
  .wearable-strip-meta { font-size: 11px; gap: 8px; flex-wrap: wrap; }
}
@media (pointer: coarse) {
  .wearable-strip-sync,
  .wearable-strip-reorder { min-height: 44px; padding: 8px 14px; }
  .wearable-reorder-arrow { min-width: 44px; min-height: 44px; display: inline-flex; align-items: center; justify-content: center; }
  .wearable-source-picker-item { min-height: 44px; padding: 10px 12px; }
  .wearable-manual-entry-del { min-width: 44px; min-height: 44px; display: inline-flex; align-items: center; justify-content: center; }
  .wearable-source-badge-btn { min-height: 32px; padding: 4px 10px; }
  .wearable-action { min-height: 44px; padding: 10px 16px; }
  .wearable-manual-add-btn,
  .wearable-log-save,
